te.upgradeCharacter.teleported = true\n                                                            task.wait(0.3)\n                                                        end\n                                                    end\n                                                end\n                                            end\n                                        end\n                                    end\n                                    if not NexusState.upgradeCharacter.teleported then\n                                        NexusLib:Notify({ Title = "Auto Rebirth", Message = "Could not find The Shadow, teleport failed. Continuing anyway.", Duration = 3 })\n                                    end\n                                end\n\n                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)\n                                if result and result.ok then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgraded successfully!", Duration = 2 })\n                                else\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgrade failed: " .. (result and result.msg or "unknown error"), Duration = 3 })\n                                end\n\n                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Stopped", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Rebirth", {\n        Name = "Auto Rebirth",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoRebirthRunning = value\n            if value then\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                NexusState.autoRebirthThread = task.spawn(function()\n                    while N