ition + VectntiAFK,\n                            }\n                            NexusState.SmartWeather.activeOverride = true\n                            NexusState.SmartWeather.targetIsland = matchedIsland\n\n                            for _, v in ipairs(NexusState.islands) do\n                                if v.name:lower() == matchedIsland:lower() then\n                                    hrp.AssemblyLinearVelocity = Vector3.zero\n                                    hrp.AssemblyAngularVelocity = Vector3.zero\n                                    hrp.CFrame = CFrame.new(v.cframe.Position + Vector3.new(0, 5, 0))\n                                    break\n                                end\n                            end\n\n                            Fishing.Flags.AutoCast = false\n                            Fishing.Flags.AutoFarmBoss = false\n                            Fishing.Flags.AutoFarmSecretBoss = true\n                            Fishing.Flags.AnchorLock = true\n                            Fishing.Flags.AutoSkill = true\n                            Fishing.Flags.AutoSkillCheck = true\n                            Fishing.Flags.AntiAFK = true\n\n                            NexusLib:Notify({\n                                Title = "Farm On Weather",\n                                Message = "Weather detected: " .. currentWeather:upper() .. "! Auto-hopping to " .. matchedIsland .. " cau Secret.",\n                                Duration = 4\n                            })\n                        end\n                    end\n                else\n                    if NexusState.SmartWeather.activeOverride then\n                        NexusLib:Notify({\n                            Title = "Farm On Weather",\n                            Message = "Weather ended! Returning to the original farm...",\n                            Duration = 3\n                        })\n                        local char = LocalPlayer.Character\n                      