                    root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })\n\n    local function displayStats()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return end\n        local cash = userData:FindFirstChild(\"Cash\") and userData.Cash.Value or 0\n        local level = userData:FindFirstChild(\"Level\") and userData.Level:FindFirstChild(\"Level\") and userData.Level.Level.Value or 0\n        local crystal = userData:FindFirstChild(\"Crystal\") and userData.Crystal.Value or 0\n        local ticket = userData:FindFirstChild(\"Ticket\") and userData.Ticket.Value or 0\n        NexusLib:Notify({\n            Title = \"Resources\",\n            Message = string.format(\"Cash: %.2fB | Level: %d | Crystal: %d | Ticket: %d\", cash/1e9, level, crystal, ticket),\n            Duration = 4\n        })\n    end\n    UpgradeSection:CreateButton({ Name = \"Check Resources\", Callback = displayStats })\nend\n\n-- ============================================================\n-- ===== TELEPORT TAB =====\n-- ============================================================\ndo\n    local TeleportTab = Window:CreateTab(\"Teleport\")\n    local TPSection = TeleportTab:CreateSection(\"NPC & Weather\", \"Left\")\n\n    TPSection:CreateButton({\n        Name = \"TP to Taoist\",\n        Callback = function()\n            local taoist = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                    taoist = v\n                    break\n                end\n            end\n            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Maoshan\",\n        Callback = function()\n            local maoshan = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                    maoshan = v\n                    break\n                end\n            end\n            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Spirit\",\n        Callback = function()\n            local godFolder = Workspace:FindFirstChild(\"NPC\") and Workspace.NPC:FindFirstChild(\"God\")\n            if not godFolder then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Folder God not found!\", Duration = 3 })\n                return\n            end\n            local target = nil\n            for _, child in pairs(godFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Model\") then\n                    local hrp = child:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        target = hrp\n                        break\n                    end\n                elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BasePart\") then\n                    target = child\n                    break\n                end\n            end\n            if not target then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"No Spirit found!\", Duration = 3 })\n                return\n            end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n            if hrp then\n                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Teleported to Spirit!\", Duration = 3 })\n            end\n        end\n    })\n\n    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====\n    do\n        local GiveSection = TeleportTab:CreateSection(\"Quest NPC & Give Fish\", \"Right\")\n\n        local function npcRoot()\n            return Workspace:FindFirstChild(\"NPC\")\n        end\n\n        local function findNpcHrp(npcName)\n            local hrp = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                if not npcFolder then return end\n                local f = npcFolder:FindFirstChild(\"Function\")\n                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)\n                if m then hrp = m:FindFirstChild(\"HumanoidRootPart\") or m:FindFirstChild(\"Torso\") end\n            end)\n            return hrp\n        end\n\n        local function teleportNearNpc(npcName, offset)\n            local hrp = findNpcHrp(npcName)\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not hrp or not root then return false end\n            pcall(function()\n                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))\n            end)\n            return true\n        end\n\n        local function parseWeightKg(text)\n            local clean = string.gsub(text, \"[,%s]\", \"\")\n            local num, suffix = string.match(clean, \"(%d+%.?%d*)([KkMmBbTt]?)\")\n            local n = tonumber(num) or 0\n            if suffix == \"K\" or suffix == \"k\" then\n                n = n * 1000\n            elseif suffix == \"M\" or suffix == \"m\" then\n                n = n * 1000000\n            elseif suffix == \"B\" or suffix == \"b\" then\n                n = n * 1000000000\n            elseif suffix == \"T\" or suffix == \"t\" then\n                n = n * 1000000000000\n            end\n            return n\n        end\n\n        local function getFishKg(item)\n            local w = 0\n            pcall(function()\n                local attr = item:GetAttribute(\"Weight\")\n                if tonumber(attr) and tonumber(attr) > 0 then\n                    w = tonumber(attr)\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"StringValue\") then\n                    local parts = {}\n                    for part in string.gmatch(item.Value, \"[^|]+\") do table.insert(parts, part) end\n                    if #parts >= 2 then w = parseWeightKg(parts[2]) end\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"NumberValue\") or item:IsA(\"IntValue\") then\n                    w = tonumber(item.Value) or 0\n                end\n            end)\n            return w\n        end\n\n        local function collectBigFish(minKg)\n            local out = {}\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            local inv = userData and userData:FindFirstChild(\"Inventory\")\n            if not inv then return out end\n            for _, item in pairs(inv:GetChildren()) do\n                local kg = getFishKg(item)\n                if kg >= minKg then\n                    table.insert(out, { item = item, name = item.Name, kg = kg })\n                end\n            end\n            table.sort(out, function(a, b) return a.kg > b.kg end)\n            return out\n        end\n\n        local function giveFishToDumbGuy(entry)\n            if not entry or not entry.item then return false end\n            local model = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                local f = npcFolder and npcFolder:FindFirstChild(\"Function\")\n                model = f and f:FindFirstChild(\"Dumb guy\")\n            end)\n      Name = \"Island Selection Mode\",\n        Options = {\"Auto Select Island\", \"Choose Island Manual\"},\n        Default = \"Auto Select Island\",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == \"Choose Island Manual\" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })\n\n    -- Create the default island dropdown (hidden, shown only in manual mode)\n    -- Not built up front, only once manual is picked\n\n    -- ===== Target island resolver =====\n    local function getTargetIsland()\n        if selectedIslandMode == \"Auto Select Island\" then\n            return getRecommendedIsland()\n        else\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == selectedIslandName then\n                    return island\n                end\n            end\n            return nil\n        end\n    end\n\n\n    local function parseQuestString(str)\n        if not str or str == \"\" then return nil, nil end\n        local parts = {}\n        for part in string.gmatch(str, \"[^,]+\") do table.insert(parts, part) end\n        if #parts >= 3 then\n            local target = nil\n            local typ = nil\n            if string.find(parts[1], \"Boss\") then\n                target = tonumber(parts[3])\n                typ = parts[1]\n            else\n                target = tonumber(parts[2])\n                typ = parts[3]\n            end\n            if target and typ then return target, typ end\n        end\n        return nil, nil\n    end\n\n    local function getCurrentQuestProgress()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return nil end\n        local quest = userData:FindFirstChild(\"Quest\")\n        if not quest then return nil end\n        local main = quest:FindFirstChild(\"Main\")\n        if not main then return nil end\n        for _, folder in pairs(main:GetChildren()) do\n            if typeof(folder) == \"Instance\" and typeof(folder) == \"Instance\" and folder:IsA(\"Folder\") and (folder.Name == \"Easy Ticket Quest\" or folder.Name == \"Hard Ticket Quest\") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        if child.Name == \"1\" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild(\"Objective\")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"StringValue\") and child.Name == \"1\" then\n                            local val = child.Value\n                            if val and val ~= \"\" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress()\n        if current and target and questName then\n            NexusState.ticketTargetCount = target\n            NexusState.ticketCurrentCount = current\n            NexusState.ticketQuestActive = true\n            if current >= target then\n                if not NexusState.ticketQuestClaimed then\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Complete! Claiming reward...\", Duration = 2 })\n                    -- TP to NPC, turn in with retries, chain next quest right away.\n                    local turnedIn = false\n                    for _ = 1, 5 do\n                        if ticketGoFire(\"Quest\") then\n                            for _ = 1, 6 do\n                                task.wait(0.15)\n                                if not getCurrentQuestProgress() then\n                                    turnedIn = true\n                                    break\n                                end\n                            end\n                        end\n                        if turnedIn then break end\n                        task.wait(0.2)\n                    end\n                    if turnedIn then\n                        NexusState.ticketQuestClaimed = true\n                        NexusState.ticketLastFire = 0\n                        NexusState.ticketFailCount = 0\n                        NexusState.isDoingUseBaitQuest = false\n                        disableAllFishing()\n                        NexusState.ticketQuestActive = false\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turned in. Claim toggle takes next quest.\", Duration = 3 })\n                    else\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turn-in failed, retrying...\", Duration = 2 })\n                    end\n                end\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                NexusState.ticketQuestActive = false\n                return\n            end\n            NexusState.ticketQuestClaimed = false\n\n            -- Teleport to target island (manual choice wins)\n            local targetIsland = getTargetIsland()\n            if targetIsland then\n                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                if hrp then\n                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)\n                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then\n                        NexusState.ticketLastTele = tick()\n                        safeTeleport(hrp, CFrame.new(targetPos))\n                    end\n                end\n            end\n\n                        local need = string.lower(tostring(typ or \"\") .. \" \" .. tostring(NexusState.ticketObjectiveText or \"\"))\n            local function needHas(...)\n                for _, k in ipairs({...}) do\n                    if string.find(need, k, 1, true) then return true end\n                end\n                return false\n            end\n            NexusState.isDoingUseBaitQuest = false\n            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.\n            -- No boss quests here, so boss words inside fish names must not trigger boss farm.\n            if needHas(\"usebait\", \"use bait\", \"bait\") then\n                NexusState.isDoingUseBaitQuest = true\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AnchorLock = true\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                MiscFlags.AutoBuy = true\n                local buyable = GetBuyableBaits()\n                local found = false\n                for _, name in ipairs(buyable) do\n                    if name == \"Basic Bait\" then\n                        NexusState.selectedBait = name\n                        found = true\n                        break\n                    end\n                end\n                if not found then\n                    NexusState.selectedBait = buyable[1] or \"No bait available\"\n                end\n                MiscFlags.AutoEquipBait = true\n            elseif needHas(\"skill\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                Fishing.Flags.AnchorLock = true\n            elseif needHas(\"weight\", \"kg\", \"heavy\", \"1.5m\", \"1,5m\", \"1500000\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            elseif needHas(\"fish\", \"catch\", \"fishing\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            else\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n            end\n        else\n            if NexusState.ticketQuestActive then\n                NexusState.ticketQuestActive = false\n                NexusState.ticketTargetCount = 0\n                NexusState.ticketCurrentCount = 0\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                disableAllFishing()\n            end\n            NexusState.isDoingUseBaitQuest = false\n            NexusState.ticketQuestClaimed = false\n            NexusState.ticketLastFire = 0\n            NexusState.ticketFailCount = 0\n            NexusState.ticketObjectiveText = nil\n        end\n    end\n\n    local function startAutoDoLoop()\n        if NexusState.autoDoThread then return end\n        NexusState.autoDoThread = task.spawn(function()\n            while NexusState.autoDoRunning do\n                pcall(updateQuestStatus)\n                task.wait(1)\n            end\n            NexusState.autoDoThread = nil\n        end)\n    end\n\n    local autoDoToggle = Cfg.register(DoSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Do Ticket Quest (Fast)\", {\n        Name = \"Auto Do Ticket Quest (Fast)\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            if value then\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                startAutoDoLoop()\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Started monitoring quest objective\", Duration = 2 })\n            else\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                NexusState.autoRecommendRunning = false\n                if NexusState.autoRecommendThread then\n                    task.cancel(NexusState.autoRecommendThread)\n                    NexusState.autoRecommendThread = nil\n                end\n                disableAllFishing()\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Do Ticket Quest (Fast)\", {\n        Name = \"Auto Do Ticket Quest (Fast)\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            print([[\n _   _  _______   ___   _ _____   _   _ _   _______\n| \\ | ||  ___\\ \\ / / | | /  ___| | | | | | | | ___ \\\n|  \\| || |__  \\ V /| | | \\ `--.  | |_| | | | | |_/ /\n| . ` ||  __| /   \\| | | |`--. \\ |  _  | | | | ___ \\\n| |\\  || |___/ /^\\ \\ |_| /\\__/ / | | | | |_| | |_/ /\n\\_| \\_/\\____/\\/   \\/\\___/\\____/  \\_| |_/\\___/\\____/   (sieu vip he he)\n]])\n\n-- ============================================================\n-- HTTP SPY GUARD REMOVED\n-- ============================================================\nlocal _raw_request, _raw_HttpGet, _raw_HttpPost = nil, nil, nil\n\nlocal function isFunctionHooked(fn)\n    if type(fn) ~= \"function\" then return false end\n    if ishooked and ishooked(fn) then return true end\n    return false\nend\n\nlocal function corruptExecution(reason)\n    return\n    task.spawn(function()\n        pcall(function()\n            local StarterGui = game:GetService(\"StarterGui\")\n            StarterGui:SetCore(\"SendNotification\", {\n                Title = \"Nexus Security\",\n                Text = \"Tamper detected: \" .. tostring(reason),\n                Duration = 10\n            })\n        end)\n        task.wait(2)\n        pcall(function()\n            local lp = game:GetService(\"Players\").LocalPlayer\n            if lp then lp:Kick(\"Nexus Security: Tamper detected (\" .. tostring(reason) .. \")\") end\n        end)\n        while true do end\n    end)\nend\n\nlocal function verifyHttpIntegrity()\n    return true\nend\nverifyHttpIntegrity()\n\n\n\n-- ============================================================\n-- ===== BOOT DIAGNOSTIC / CHONG CHET IM LANG =====\n-- Nhieu executor (nhat la UNC/sUNC cao tren mobile) KHONG hien console,\n-- nen khi script chet giua duong thi nguoi dung chi thay \"khong len gi\".\n-- Block nay dam bao MOI that bai deu hien ra man hinh: ve banner bang\n-- Instance.new thuan -> khong can NexusLib, khong can CoreGui, khong can console.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n\n    -- Don banner cua lan execute truoc\n    pcall(function()\n        if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n    end)\n    _rt.NexusBootGui = nil\n\n    local boot = { stage = \"bat dau\", done = false }\n    _rt.NexusBoot = boot\n\n    local execName = \"?\"\n    pcall(function()\n        if identifyexecutor then execName = tostring((identifyexecutor())) end\n    end)\n\n    -- Tim cho parent ScreenGui: uu tien gethui (duoc bao ve), roi PlayerGui,\n    -- cuoi cung CoreGui. Tat ca boc pcall vi 1 so executor chan CoreGui.\n    local function guiHome()\n        local tries = {\n            function() return gethui and gethui() end,\n            function() return game:GetService(\"Players\").LocalPlayer:FindFirstChild(\"PlayerGui\") end,\n            function() return game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerGui\", 10) end,\n            function() return game:GetService(\"CoreGui\") end,\n        }\n        for _, f in ipairs(tries) do\n            local ok, v = pcall(f)\n            if ok and typeof(v) == \"Instance\" then return v end\n        end\n        return nil\n    end\n\n    local function banner(title, body)\n        local home = guiHome()\n        if not home then return false end\n        local ok = pcall(function()\n            pcall(function()\n                if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n            end)\n            local sg = Instance.new(\"ScreenGui\")\n            sg.Name = \"NexusBootReport\"\n            sg.ResetOnSpawn = false\n            sg.IgnoreGuiInset = true\n            sg.DisplayOrder = 2147483647\n            sg.Parent = home\n            _rt.NexusBootGui = sg\n\n            local frame = Instance.new(\"Frame\")\n            frame.Size = UDim2.new(0, 400, 0, 175)\n            frame.Position = UDim2.new(0.5, -200, 0, 30)\n            frame.BackgroundColor3 = Color3.fromRGB(30, 21, 26)\n            frame.BorderSizePixel = 0\n            frame.Parent = sg\n\n            local corner = Instance.new(\"UICorner\")\n            corner.CornerRadius = UDim.new(0, 10)\n            corner.Parent = frame\n\n            local stroke = Instance.new(\"UIStroke\")\n            stroke.Color = Color3.fromRGB(232, 88, 100)\n            stroke.Thickness = 2\n            stroke.Parent = frame\n\n            local head = Instance.new(\"TextLabel\")\n            head.Size = UDim2.new(1, -20, 0, 26)\n            head.Position = UDim2.new(0, 12, 0, 9)\n            head.BackgroundTransparency = 1\n            head.Font = Enum.Font.GothamBold\n            head.TextSize = 16\n            head.TextColor3 = Color3.fromRGB(255, 122, 132)\n            head.TextXAlignment = Enum.TextXAlignment.Left\n            head.Text = tostring(title)\n            head.Parent = frame\n\n            local body2 = Instance.new(\"TextLabel\")\n            body2.Size = UDim2.new(1, -24, 1, -74)\n            body2.Position = UDim2.new(0, 12, 0, 38)\n            body2.BackgroundTransparency = 1\n            body2.Font = Enum.Font.Gotham\n            body2.TextSize = 13\n            body2.TextColor3 = Color3.fromRGB(236, 236, 242)\n            body2.TextWrapped = true\n            body2.TextXAlignment = Enum.TextXAlignment.Left\n            body2.TextYAlignment = Enum.TextYAlignment.Top\n            body2.Text = tostring(body)\n            body2.Parent = frame\n\n            local foot = Instance.new(\"TextLabel\")\n            foot.Size = UDim2.new(1, -100, 0, 16)\n            foot.Position = UDim2.new(0, 12, 1, -26)\n            foot.BackgroundTransparency = 1\n            foot.Font = Enum.Font.Gotham\n            foot.TextSize = 11\n            foot.TextColor3 = Color3.fromRGB(150, 150, 162)\n            foot.TextXAlignment = Enum.TextXAlignment.Left\n            foot.Text = \"executor: \" .. execName\n            foot.Parent = frame\n\n            local close = Instance.new(\"TextButton\")\n            close.Size = UDim2.new(0, 72, 0, 24)\n            close.Position = UDim2.new(1, -84, 1, -32)\n            close.BackgroundColor3 = Color3.fromRGB(62, 46, 53)\n            close.Font = Enum.Font.GothamBold\n            close.TextSize = 12\n            close.TextColor3 = Color3.fromRGB(255, 255, 255)\n            close.Text = \"Dong\"\n            close.AutoButtonColor = true\n            close.Parent = frame\n\n            local cc = Instance.new(\"UICorner\")\n            cc.CornerRadius = UDim.new(0, 6)\n            cc.Parent = close\n\n            close.MouseButton1Click:Connect(function()\n                pcall(function() sg:Destroy() end)\n            end)\n        end)\n        return ok\n    end\n\n    -- Bao loi ra MOI kenh co the co\n    _rt.NexusReport = function(title, body)\n        local line = \"[Nexus] \" .. tostring(title) .. \" | \" .. tostring(body)\n        pcall(function() print(line) end)\n        pcall(function() warn(line) end)\n        pcall(function() if rconsoleprint then rconsoleprint(line .. \"\\n\") end end)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then\n                slib:Notify({ Title = tostring(title), Message = tostring(body), Duration = 14 })\n            end\n        end)\n        pcall(function() banner(title, body) end)\n    end\n\n    -- Danh dau dang o buoc nao (watchdog se in ra buoc nay neu treo)\n    _rt.NexusStage = function(name)\n        if _rt.NexusBoot == boot then boot.stage = tostring(name) end\n    end\n\n    -- Cho co cua so / con children -> bao ro thay vi treo im lang\n    _rt.NexusNeedChild = function(parent, childName, timeout)\n        timeout = timeout or 30\n        if typeof(parent) ~= \"Instance\" then\n            _rt.NexusReport(\"Nexus: failed to start\",\n                \"No parent to search for '\" .. tostring(childName) .. \"'.\")\n            return nil\n        end\n        local ok, inst = pcall(function()\n            return parent:WaitForChild(childName, timeout)\n        end)\n        if ok and inst then return inst end\n        _rt.NexusReport(\"Nexus: game data missing\",\n            \"Could not find '\" .. tostring(childName) .. \"' sau \" .. tostring(timeout) .. \"s.\\n\" ..\n            \"1) Wrong game? This script is only for [UPD] Heavyweight Fishing.\\n\" ..\n            \"2) If you just joined, wait for the game to load, then execute again.\")\n        return nil\n    end\n\n    -- WATCHDOG: 50s ma UI chua len -> bao dang tac o buoc nao.\n    -- Day la cai bat MOI loi chet im lang, ke ca loi tuong lai chua biet.\n    task.spawn(function()\n        for _ = 1, 50 do\n            task.wait(1)\n            if _rt.NexusBoot ~= boot then return end\n            if boot.done then return end\n        end\n        if _rt.NexusBoot ~= boot or boot.done then return end\n        _rt.NexusReport(\"Nexus: the script failed to start\",\n            \"Stopped at stage: \" .. tostring(boot.stage) .. \"\\n\" ..\n            \"Screenshot this panel and send it to the admin.\")\n    end)\nend\n-- ===== END BOOT DIAGNOSTIC =====\n\n-- ============================================================\n-- ===== ANTI-BYPASS GUARD (freemium) v2 =====\n-- Chan chay chua: phai co key hop le HOAC da duoc Key System xac thuc.\n-- An toan: khong kick khi loi mang / executor khong ho tro http.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n    pcall(function() _rt.NexusStage(\"key check\") end)\n\n    local Players = game:GetService(\"Players\")\n    local HttpService = game:GetService(\"HttpService\")\n    local LP = Players.LocalPlayer\n\n    -- Anti-Hook / Anti-Dump check\n    local _raw_loadstring = loadstring\n    local function isHooked(f)\n        if type(f) ~= \"function\" then return false end\n        if ishooked and ishooked(f) then return true end\n        return false\n    end\n    if isHooked(_raw_loadstring) or (loadstring and isHooked(loadstring)) then\n        LP:Kick(\"Nexus Security: loadstring tampering detected.\")\n        while true do task.wait(9999) end\n        return\n    end\n\n    local GUARD = {\n        API_URL = \"https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system\",\n        PROTOCOL_VERSION = 3,\n        -- Freemium chi doc file FREEMIUM (khong doc file premium de tranh de lan)\n        KEY_FILES = { \"NexusFreemiumKey.txt\" },\n        TIMEOUT = 20,\n        RETRY = 2,\n        -- Doi thanh true neu muon: khong tim thay key thi VAN CHAY (che do offline).\n        OFFLINE_FALLBACK = true,\n    }\n\n    local function getHWID()\n        local candidates = {\n            function() return gethwid and gethwid() end,\n            function() return game:GetService(\"RbxAnalyticsService\"):GetClientId() end,\n        }\n        for _, getter in ipairs(candidates) do\n            local ok, value = pcall(getter)\n            if ok and type(value) == \"string\" and #value >= 8 then\n                return value .. \":\" .. tostring(LP.UserId)\n            end\n        end\n        return string.format(\"player:%d:place:%d\", LP.UserId, game.PlaceId)\n    end\n\n    local _raw_req = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    local function requestAdapter()\n        return _raw_req or (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    end\n\n    local function api(action, fields)\n        local payload = fields or {}\n        payload.action = action\n        payload.protocol_version = GUARD.PROTOCOL_VERSION\n        payload.hwid = getHWID()\n        local lastErr = \"NETWORK_ERROR\"\n        for _ = 1, GUARD.RETRY do\n            local ok, result = pcall(function()\n                local requestFn = requestAdapter()\n                local encoded = HttpService:JSONEncode(payload)\n                if requestFn then\n                    local raw = requestFn({\n                        Url = GUARD.API_URL, Method = \"POST\",\n                        Headers = { [\"Content-Type\"] = \"application/json\" },\n                        Body = encode",
