1,59626,2049.,"upQn",23548,'st appeared in the server. Join fast!",\n                color = 0xFF6B35,\n                fields = {\n                    { name = "\xF0\x9F\x94\x97 Join Server (tap to copy)", value = "NEXUSHUB|" .. encodedJobId, inline = false },\n                    { name = "\xF0\x9F\x91\xA5 Players", value = "`" .. playerStr .. "`", inline = true },\n                    { name = "\xE2\x8F\xB0 Time", value = "`" .. timeStr .. "`", inline = true },\n                },\n                footer = { text = "Nexus Hub Event Scanner" },\n                timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = "POST",\n                Headers = { ["Content-Type"] = "application/json" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendServerEvent(eventName, attributes)\n        local httpRequest = (typeof(request) == "function" and request) or (typeof(http_request) == "function" and http_request) or (syn and typeof(syn.request) == "function" and syn.request) or (http and typeof(http.request) == "function" and http.request)\n        if not httpRequest or SERVER_HOP_API_BASE == "" then return false end\n        local body = HttpService:JSONEncode({ event_id = tostring(eventName) .. "-" .. tostring(os.time()), place_id = game.PlaceId, job_id = game.JobId, reason = tostring(eventName), attributes = attributes or {}, source = "nexus_hub" })\n        local ok = pcall(httpRequest, { Url = SERVER_HOP_API_BASE:gsub("/$", "") .. "/v1/hop-events", Method = "POST", Headers = { ["Content-Type"] = "application/json", ["X-API-Key"] = SERVER_HOP_API_KEY }, Body = body })\n        return ok\n    end\n\n    local function sendWeatherWebhook(url, weatherName)\n        local httpRequest = (typeof(request) == "function" and request) or (typeof(http_request) == "function" and http_request) or (syn and typeof(syn.request) == "function" and syn.request) or (http and typeof(http.request) == "function" and http.request)\n        if not httpRequest or url == "" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. "/" .. Players.MaxPlayers\n        local timeStr = os.date("%Y-%m-%d %H:%M:%S")\n        local weatherEmoji = {\n            ["Rainy"] = "\xF0\x9F\x8C\xA7\xEF\xB8\x8F", ["Thunderstorm"] = "\xE2\x9B\x88\xEF\xB8\x8F", ["Foggy"] = "\xF0\x9F\x8C\xAB\xEF\xB8\x8F",\n            ["Windy"] = "\xF0\x9F\x92\xA8", ["Snowy"] = "\xE2\x9D\x84\xEF\xB8\x8F", ["Blazing Sun"] = "\xE2\x98\x80\xEF\xB8\x8F"\n        }\n        local colors = {\n            ["Rainy"] = 0x2A75BB, ["Thunderstorm"] = 0x800080, ["Foggy"] = 0x808080,\n            ["Windy"] = 0x87CEEB, ["Snowy"] = 0xFFFAFA, ["Blazing Sun"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or "\xF0\x9F\x8C\xA6\xEF\xB8\x8F"\n        local embedColor = colors[weatherName] or 0x00A2FF\n        local payload = HttpService:JSONEncode({\n            username = "Nexus Hub",\n            content = "",\n            embeds = {{\n                title = emoji .. " Weather Alert: " .. weatherName .. "!",\n                description = "Special weather is active right now. Perfect time to fish!",\n                color = embedColor,\n                fields = {\n                    { name = "\xF0\x9F\x94\x97 Join Server (tap to copy)", value = "NEXUSHUB|" .. encodedJobId, inline = false },\n                    { name = "\xF0\x9F\x91\xA5 Players", value = "`" .. playerStr .. "`", inline = true },\n                    { name = "\xE2\x8F\xB0 Time", value = "`" .. timeStr .. "`", inline = true },\n                },\n                footer = { text = "Nexus Hub Weather Alert" },\n                timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = "POST",\n                Headers = { ["Content-Type"] = "application/json" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function watchEnzoReady()\n        local wasReady = false\n        while alive() do\n            local ready = false\n            pcall(function()\n                local root = Workspace:FindFirstChild("Bosses") or Workspace:FindFirstChild("Boss") or Workspace:FindFirstChild("NPC")\n                local enzo = root and root:FindFirstChild("Enzo", true)\n                if enzo then\n                    local cooldown = tonumber(enzo:GetAttribute("Cooldown")) or tonumber(enzo:GetAttribute("CooldownRemaining"))\n                    local endsAt = tonumber(enzo:GetAttribute("CooldownEnd"))\n                    ready = enzo:GetAttribute("CanAttack") == true or enzo:GetAttribute("Ready") == true or (cooldown and cooldown <= 0) or (endsAt and endsAt <= os.clock())\n                end\n            end)\n            if ready and not wasReady then sendServerEvent("Enzo Ready", { boss = "Enzo", ready = true }) end\n            wasReady = ready\n            task.wait(0.5)\n        end\n    end\n\n    local function sendSpiritWebhook()\n        sendServerEvent("SPIRIT", { npc = "God" })\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("MainGui")\n        if mg then\n            local info = mg:FindFirstChild("Info")\n            if info then\n                local infoFrame = info:FindFirstChild("Info")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild("Weather")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild("Value")\n                        if val and typeof(val) == "Instance" then\n                            local text = (typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value)\n                            return text:gsub("Weather:%s*", "")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild("NPC")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and (string.find(v.Name:lower(), "maoshan") or string.find(v.Name:lower(), "merchant")) and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendServerEvent("Maoshan NPC", { npc = "Maoshan" })\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and string.find(v.Name:lower(), "taoist") and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendServerEvent("Taoist NPC", { npc = "Taoist" })\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild("NPC")\n                if npcF and npcF:FindFirstChild("God") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendServerEvent("SPIRIT", { npc = "God" })\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= "Clear" and uiWeather ~= "" then\n                current = uiWeather\n            else\n                for _, w in ipairs({"Rainy", "Thunderstorm", "Foggy", "Windy", "Snowy", "Blazing Sun"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= "clear" then\n            NexusState.LastWeather = current\n            sendServerEvent("Weather", { weather = current })\n        end\n    end\n\n    task.spawn(function()\n        task.spawn(watchEnzoReady)\n        local npcFolder = Workspace:WaitForChild("NPC", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild("PlayerGui", 30):WaitForChild("MainGui", 30)\n            local info = mg and mg:WaitForChild("Info", 15)\n            local infoFrame = info and info:WaitForChild("Info", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild("Weather", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild("Value", 15)\n            if val and typeof(val) == "Instance" then\n                local signal\n                if val:IsA("TextLabel") or val:IsA("TextButton") then signal = val:GetPropertyChangedSignal("Text") else signal = val:GetPropertyChangedSignal("Value") end\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFoldere.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild("FavoriteItem")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = "Auto Favourite", Message = "FavoriteItem remote not found!", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == "function" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild("Inventory")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, "| Favorite$") then\n                                        local fishName = fullName:match("^(.-)%s*|") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Enabled - scanning every 0.3s", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = "Auto Favourite", Message = "Disabled", Duration = 2 })\n                end\n            end\n        })\n    end\n    -- ===== AUTO PRAY SPIRIT =====\n    do\n        local PraySection = FarmingTab:CreateSection("Auto Pray Spirit")\n        local prayEnabled = false\n        local prayThread = nil\n        local prayConnections = {}\n        local lastInteractTime = 0\n        local cooldown = 2 -- seconds between interactions\n\n        -- Scan and handle spirits\n        local function scanAndPray()\n            local godFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("God")\n            if not godFolder then return end\n\n            local now = tick()\n            if now - lastInteractTime < cooldown then return end\n\n            -- Find every model in the God folder (sub-models included)\n            local models = {}\n            for _, child in ipairs(godFolder:GetDescendants()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Model") then\n                    table.insert(models, child)\n                end\n            end\n\n            for _, model in ipairs(models) do\n                -- Find HumanoidRootPart or PrimaryPart\n                local hrp = model:FindFirstChild("HumanoidRootPart")\n                if not hrp then\n                    hrp = model.PrimaryPart\n                end\n                if hrp then\n                -- Find Talk and ProximityPrompt\n                local talk = hrp:FindFirstChild("Talk")\n                if talk then\n                local prompt = talk:FindFirstChild("ProximityPrompt")\n                if prompt then\n                -- Configure ProximityPrompt\n                pcall(function()\n                    prompt.RequiresLineOfSight = false\n                    prompt.HoldDuration = 0\n                end)\n\n                -- Teleport to the spirit position\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = hrp.CFrame + Vector3.new(0, 2, 0)\n                    end\n                end\n\n                -- Trigger ProximityPrompt\n                local success = false\n                -- Cach 1: Fire Proximity Prompt\n                if fireproximityprompt and prompt then\n                    pcall(function()\n                        fireproximityprompt(prompt)\n                        success = true\n                    end)\n                end\n                -- Method 2: firesignal\n                if firesignal and prompt then\n                    pcall(function()\n                        firesignal(prompt.PromptButtonHoldBegan)\n                        task.wait(0.1)\n                        firesignal(prompt.PromptButtonHoldEnded)\n                        success = true\n                    end)\n                end\n                -- Method 2: use VirtualInputManager to press E\n                if not success then\n                    pcall(function()\n                        local vim = game:GetService("VirtualInputManager")\n                        if vim then\n                            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)\n                            task.wait(0.1)\n                            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)\n                            success = true\n                        end\n                    end)\n                end\n                -- Method 3: use VirtualUser (last fallback)\n                if not success then\n                    pcall(function()\n                        if VirtualUser then\n                            VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            task.wait(0.1)\n                            VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            success = true\n                        end\n                    end)\n                end\n\n                if success then\n                    lastInteractTime = now\n                    NexusLib:Notify({ Title = "Pray", Message = "Prayed to " .. model.Name, Duration = 2 })\n                    break -- only interact with one spirit per pass\n                end\n                end\n                end\n                end\n            end\n        end\n\n        -- Start helper\n        local function startPray()\n            if prayEnabled then return end\n            prayEnabled = true\n            prayThread = task.spawn(function()\n                while prayEnabled do\n                    pcall(scanAndPray)\n                    task.wait(1.5) -- scan every 1.5 seconds\n                end\n            end)\n            NexusLib:Notify({ Title = "Auto Pray", Message = "Enabled", Duration = 2 })\n        end\n\n        local function stopPray()\n            prayEnabled = false\n            if prayThread then\n                task.cancel(prayThread)\n                prayThread = nil\n            end\n            for _, conn in ipairs(prayConnections) do\n                pcall(function() conn:Disconnect() end)\n            end\n            prayConnections = {}\n            NexusLib:Notify({ Title = "Auto Pray", Message = "Disabled", Duration = 2 })\n        end\n\n        -- Toggle\n        Cfg.register(PraySection:CreateToggle(Cfg.wrap("Toggle", "Auto Teleport + Interact (Pray) Spirit", {\n            Name = "Auto Teleport + Interact (Pray) Spirit",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })), "Toggle", "Auto Teleport + Interact (Pray) Spirit", {\n            Name = "Auto Teleport + Interact (Pray) Spirit",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== SHOP TAB =====\n-- ============================================================\ndo\n    local ShopTab = Window:CreateTab("Shop")\n\n    -- Index\n    do\n        local IndexSection = ShopTab:CreateSection("Index")\n        IndexSection:CreateButton({\n            Name = "Unlock all fish",\n            Callback = function()\n                local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                if not userData then\n                    NexusLib:Notify({ Title = "Index", Message = "User data not found!", Duration = 2 })\n                    return\n                end\n                local indexFolder = userData:FindFirstChild("Index")\n                if not indexFolder then\n                    NexusLib:Notify({ Title = "Index", Message = "Index folder not found!", Duration = 2 })\n                    return\n                end\n                local count = 0\n                for _, child in ipairs(indexFolder:GetChildren()) do\n                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then\n                        child.Value = 1\n                        count = count + 1\n                    elseif typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("BoolValue") then\n                        child.Value = true\n                        count = count + 1\n                    end\n                end\n            end\n        })\n    end\n\n    -- Upgrade Skill\n    do\n        local UpgradeSkillSection = ShopTab:CreateSection("Upgrade Skill")\n        local function GetOwnedSkills()\n            local userId = LocalPlayer and LocalPlayer.UserId\n            if not userId then return {} end\n            local userData = Data and Data:FindFirstChild(tostring(userId))\n            if not userData then return {} end\n            local skillFolder = userData:FindFirstChild("Skill")\n            if not skillFolder then return {} end\n            local ownedSkills = {}\n            for _, child in pairs(skillFolder:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then\n                    local owned = child:FindFirstChild("Owned")\n                    if typeof(owned) == "Instance" and owned:IsA("BoolValue") and owned.Value == true then\n                        table.insert(ownedSkills, child.Name)\n                    end\n                end\n            end\n            return ownedSkills\n        end\n\n        local skillOptions = GetOwnedSkills()\n        if #skillOptions == 0 then skillOptions = {"No skill o